#!/usr/bin/env node
/**
 * One-off generator for src/language/languages.ts.
 *
 * Builds a static table of the languages that have an ISO 639-1 (alpha-2) code,
 * sourced from the iso-639-1 and iso-639-2 npm packages (devDependencies).
 * The generated file has zero runtime dependencies.
 *
 * Usage: node scripts/generate-language-table.mjs
 */
import { writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const pluginRoot = join(__dirname, '..');
const require = createRequire(join(pluginRoot, 'package.json'));

const iso6391Data = require('./node_modules/iso-639-1/src/data.js');
const { iso6392 } = require('./node_modules/iso-639-2/2.js');

const entriesByAlpha2 = new Map();
for (const entry of iso6392) {
	if (entry.iso6391) {
		entriesByAlpha2.set(entry.iso6391, entry);
	}
}

// 'bh' appears in the iso-639-2 B->1 map but has no iso-639-1 data row.
// Drop it so every alpha2 in our table is backed by a real 639-1 code.
const orphanAlpha2 = 'bh';

const table = [];
for (const [alpha2, entry] of entriesByAlpha2) {
	if (alpha2 === orphanAlpha2) continue;
	const alpha3 = entry.iso6392T || entry.iso6392B;
	const aliases = [];
	if (entry.iso6392B) aliases.push(entry.iso6392B);
	if (entry.iso6392T && entry.iso6392T !== entry.iso6392B) aliases.push(entry.iso6392T);
	table.push({ alpha2, alpha3, name: entry.name, aliases });
}

// Sort by English name for stable, diffable output.
	table.sort((a, b) => a.name.localeCompare(b.name));

const lines = [];
lines.push('/**');
lines.push(' * Generated by scripts/generate-language-table.mjs.');
lines.push(' * Do not edit by hand. Re-run `npm run generate:language-table`.');
lines.push(' *');
lines.push(' * One entry per language that has an ISO 639-1 (alpha-2) code.');
lines.push(' * Fields: alpha2 (ISO 639-1), alpha3 (ISO 639-2 terminological,');
lines.push(' * falling back to the bibliographic code), English name, and aliases');
lines.push(' * (which always include the bibliographic ISO 639-2/B code, plus the');
lines.push(' * terminological code when it differs).');
lines.push(' */');
lines.push('export interface LanguageEntry {');
lines.push('\talpha2: string;');
lines.push('\talpha3: string;');
lines.push('\tname: string;');
lines.push('\taliases: string[];');
lines.push('}');
lines.push('');
lines.push('export const LANGUAGES: LanguageEntry[] = [');
for (const e of table) {
	const aliases = e.aliases.map((a) => `'${a}'`).join(', ');
	lines.push('\t{');
	lines.push(`\t\talpha2: '${e.alpha2}',`);
	lines.push(`\t\talpha3: '${e.alpha3}',`);
	lines.push(`\t\tname: ${JSON.stringify(e.name)},`);
	lines.push(`\t\taliases: [${aliases}],`);
	lines.push('\t},');
}
lines.push('];');
lines.push('');

const outPath = join(pluginRoot, 'src/language/languages.ts');
writeFileSync(outPath, lines.join('\n'), 'utf8');
console.log(`Wrote ${outPath} with ${table.length} entries`);